import numpy as np, cv2
A=np.load('source_pixels.npz')['rgb']
hsv=np.array([cv2.cvtColor(f,cv2.COLOR_RGB2HSV) for f in A])
for name, mask in {
 'red':(((hsv[:,:,:,0]<12)|(hsv[:,:,:,0]>170))&(hsv[:,:,:,1]>100)&(hsv[:,:,:,2]>70)),
