}.items():
 print('\\n',name)
 for i,m in enumerate(mask):
  n,lab,st,ct=cv2.connectedComponentsWithStats(m.astype('uint8'))
  comps=[]
  for j in range(1,n):
   x,y,w,h,area=st[j]
   if area>=4: comps.append((area,round(ct[j,0],2),round(ct[j,1],2),x,y,w,h))
  comps=sorted(comps,reverse=True)[:3]
  if i%3==0 or name=='red': print(i,comps)
